"""HTML e CSS gerados pelo Python, sem JavaScript, CDN ou recursos externos."""
import html
import os
from urllib.parse import urlencode
from .store import connect, DEFAULT_DB
from .roles import can_page

LABELS={'sentenca':'Sentença','decisao':'Decisão interlocutória','ordinaria':'Movimentação ordinária','incerto':'Revisão necessária','pendente':'Pendente','executando':'Executando','concluida':'Concluída','falhou':'Falhou','revisado':'Revisado','superado':'Superado','revisao_necessaria':'Revisão necessária','pronto_para_revisao':'Pronto para revisão'}
NAV=[('como_usar','Como usar o site','?'),('minha_conta','Minha conta','◉'),('comercial','Comercial','↗'),('financeiro','Financeiro','▤'),('inicio','Visão geral','◈'),('processos','Processos e dossiês','▤'),('chat','Conversar com a IA','◌'),('simulador','Laboratório de eventos','⇄'),('avaliacao','Avaliação','◎'),('acervo','Acervo jurídico real','▧'),('arquitetura','Arquitetura','▦'),('economia','Viabilidade econômica','↗'),('seguranca','Segurança e operação','◇'),('auditoria','Trilha de auditoria','≡')]

def esc(v): return html.escape(str(v if v is not None else ''),quote=True)
def label(v): return LABELS.get(v,v)
def badge(v):
    style='ok' if v in ('concluida','revisado','disponível','pronto_para_revisao') else 'warn' if v in ('incerto','falhou','indisponível','revisao_necessaria') else 'muted'
    return f'<span class="badge {style}">{esc(label(v))}</span>'
def date(v): return esc(str(v or 'Ainda não coletado').replace('T',' ')[:19])
def card(title,body,extra=''): return f'<section class="card {extra}"><h2>{esc(title)}</h2>{body}</section>'
def empty(text): return f'<div class="empty"><span>◇</span><p>{esc(text)}</p></div>'
def table(headers,rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+(''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in r)+'</tr>' for r in rows) or '<tr><td colspan="9">Nenhum registro ainda.</td></tr>')+'</tbody></table></div>'

class BaseView:
    def __init__(self, token, profile='gestor', query=None, path=DEFAULT_DB):
        self.token=token; self.profile=profile; self.q=query or {}; self.path=path
    def url(self,page='inicio',**kw):
        if page=='inicio' and self.q.get('_role'):
            from .roles import home
            page=home(self.q['_role'])
        return '/?'+urlencode({'page':page,'profile':self.profile,**kw})
    def link(self,text,page='inicio',**kw): return f'<a href="{esc(self.url(page,**kw))}">{esc(text)}</a>'
    def form(self,action,text,fields=None,cls='primary'):
        vals={'csrf':self.token,'profile':self.profile,'action':action,**(fields or {})}
        hidden=''.join(f'<input type="hidden" name="{esc(k)}" value="{esc(v)}">' for k,v in vals.items())
        return f'<form method="post" action="/action" class="inline">{hidden}<button class="{cls}" type="submit">{esc(text)}</button></form>'
    def fullform(self,action,body,fields=None):
        vals={'csrf':self.token,'profile':self.profile,'action':action,**(fields or {})}
        return '<form method="post" action="/action">'+''.join(f'<input type="hidden" name="{esc(k)}" value="{esc(v)}">' for k,v in vals.items())+body+'</form>'
    def case_rows(self):
        with connect(self.path) as con:
            return [dict(r) for r in con.execute('SELECT c.*, (SELECT count(*) FROM events e WHERE e.case_id=c.id) events,(SELECT count(*) FROM alerts a WHERE a.case_id=c.id AND a.status="pendente") pending FROM cases c ORDER BY c.id') if self.profile=='gestor' or r['owner'].lower()==self.profile]
    def page(self,name):
        name=name if name in dict((n,t) for n,t,_ in NAV) else 'construcao'
        title=next((t for n,t,_ in NAV if n==name),'Página em construção')
        body=getattr(self,name)()
        nav=''.join(f'<a class="nav-item {"active" if n==name else ""}" href="{esc(self.url(n))}"><span>{icon}</span>{esc(t)}</a>' for n,t,icon in NAV if (n!='chat' or self.profile=='gestor') and (not self.q.get('_role') or can_page(self.q['_role'],n)))
        options=''.join(f'<option value="{p}" {"selected" if p==self.profile else ""}>{l}</option>' for p,l in [('gestor','Gestor · todos os casos'),('ana','Ana · carteira própria'),('bruno','Bruno · carteira própria')])
        switch=f'<form method="get"><input type="hidden" name="page" value="{name}"><label for="profile">Perfil de demonstração</label><div class="profile-switch"><select id="profile" name="profile">{options}</select><button class="small secondary">Trocar</button></div></form>'
        if self.q.get('_role'):
            from .roles import ROLES
            switch=f'<div><strong>{esc(self.q.get("_name",self.q["_username"]))}</strong><br><small>{esc(ROLES[self.q["_role"]])}</small></div>'
        logout=f'<form method="post" action="/logout" class="inline"><input type="hidden" name="csrf" value="{esc(self.token)}"><button class="secondary small">Sair</button></form>'
        msg=self.q.get('msg','')
        notice=f'<div class="notice" role="status">{esc(msg)}</div>' if msg else ''
        with connect(self.path) as con:
            active=con.execute("SELECT count(*) FROM tasks WHERE status IN ('pendente','executando')").fetchone()[0]
        refresh='<meta http-equiv="refresh" content="4">' if active and name in ('inicio','processos','simulador') else ''
        if name=='chat' and self.profile=='gestor':
            try: conversation=int(self.q.get('conversation',0))
            except (ValueError,TypeError): conversation=0
            with connect(self.path) as con:
                waiting=con.execute("SELECT 1 FROM chat_turns WHERE conversation_id=? AND status IN ('pendente','executando')",(conversation,)).fetchone()
            if waiting: refresh='<meta http-equiv="refresh" content="3">'
        return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">{refresh}<title>{esc(title)} · Amoras Jurídicas</title><link rel="stylesheet" href="/style.css"></head>
<body><a class="skip" href="#main">Pular para conteúdo</a><aside><a class="brand" href="{esc(self.url())}"><img class="brand-logo" src="/static/img/logotipo.webp" alt=""><span>Amoras<span class="brand-sub">JURÍDICAS</span></span></a><p class="nav-label">PAINEL LOCAL</p><nav>{nav}</nav><div class="side-bottom"><span class="dot"></span> Local e sem chamadas pagas<p>Python · SQLite · código aberto</p><small>Dados processuais 100% sintéticos.</small></div></aside>
<div class="workspace"><header><div><span class="eyebrow">CASE AI ENGINEER</span><span class="header-divider">/</span><span>Laboratório jurídico</span></div><span class="local-pill"><span class="dot"></span> localhost</span>{logout}</header><main id="main"><div class="heading"><div><p class="eyebrow purple">MONITORAMENTO PROCESSUAL</p><h1>{esc(title)}</h1><p class="subtitle">Dados, execução e revisão em um só lugar.</p></div><div class="profile-box">{switch}</div></div><div class="synthetic"><strong>SIMULAÇÃO</strong><span>Processos fictícios · acervo STJ de 2016 · inferência local</span></div>{notice}{body}</main><footer>Amoras Jurídicas · Protótipo de arquitetura <span>Sem protocolo automático · Sem cálculo de prazo · Sem aconselhamento jurídico</span></footer></div></body></html>'''
